class BtsInfo(GenericEMSSIMCommand):
    """Btsinfo command class."""

    def __init__(self, connection, prompt=None, newline_chars=None, runner=None):
        """
        Btsinfo command.

        :param connection: moler connection to device, terminal when command is executed.
        :param prompt: expected prompt sending by device after command execution
        :param newline_chars: Characters to split lines
        :param runner: Runner to run command
        """
        super(BtsInfo, self).__init__(connection, prompt=prompt, newline_chars=newline_chars, runner=runner)
        self._current_main_header = None
        self._current_cell_header = None
        self._columns_headers = None

    def build_command_string(self):
        """
        Build command string from parameters passed to object.

        :return: String representation of command to send over connection to device.
        """
        cmd = "bts_info"
        return cmd

    def on_new_line(self, line, is_full_line):
        """
        Put your parsing code here.

        :param line: Line to process, can be only part of line. New line chars are removed from line.
        :param is_full_line: True if line had new line chars, False otherwise
        :return: None
        """
        if is_full_line:
            try:
                self._parse_failure(line)
                self._parse_main_headers(line)
                self._parse_cell_headers(line)
                self._parse_key_value(line)
                self._parse_links_states(line)
            except ParsingDone:
                pass  # line has been fully parsed by one of above parse-methods
        return super(BtsInfo, self).on_new_line(line, is_full_line)

    #     |BTS properties
    _re_main_header = re.compile(r'^\s+\|(?P<MAIN_HEADER>[A-Z][\w\s]+)$')

    def _parse_main_headers(self, line):
        if self._regex_helper.search_compiled(BtsInfo._re_main_header, line):
            self._current_main_header = self._regex_helper.group("MAIN_HEADER")
            self._current_main_header = self._clean_key(self._current_main_header)
            self.current_ret[self._current_main_header] = {}
            self._columns_headers = None
            raise ParsingDone

    #     |                Cell 1
    _re_cell_header = re.compile(r'^\s+\|\s+(?P<CELL_HEADER>\w+\s\d+)')

    def _parse_cell_headers(self, line):
        if self._regex_helper.search_compiled(BtsInfo._re_cell_header, line):
            self._current_cell_header = self._regex_helper.group("CELL_HEADER")
            self._current_cell_header = self._clean_key(self._current_cell_header)
            self.current_ret[self._current_main_header][self._current_cell_header] = {}
            raise ParsingDone

    #     |                Site name:                      FZM-TDD-249
    #     |                Uplink (RX) carrier:
    _re_key_value = re.compile(r'^\s+\|\s+(?P<KEY>.*):\s?(\s*(?P<VALUE>.*))?$')

    def _parse_key_value(self, line):
        if self._regex_helper.search_compiled(BtsInfo._re_key_value, line):
            key = self._regex_helper.group("KEY")
            value = self._regex_helper.group("VALUE") if self._regex_helper.group("VALUE") is not None else ""
            value = value.replace("\r", "")

            key = self._clean_key(key)
            value = convert_to_number(value)

            if self._current_cell_header:
                self.current_ret[self._current_main_header][self._current_cell_header][key] = value
            else:
                self.current_ret[self._current_main_header][key] = value
            raise ParsingDone

    #      |                Object          Operational     Administrative
    _re_links_states = re.compile(r'^\s+\|\s+.*$')

    def _parse_links_states(self, line):
        if self._regex_helper.search_compiled(self._re_links_states, line):
            matched = re.findall(r"([\w\.\-]+(\s[\w\.\-]+)*)", line)
            matched = [match[0] for match in matched]

            if self._columns_headers:
                self._fill_dict(matched)
                raise ParsingDone
            else:
                self._columns_headers = matched

    # 09:29:34          |ERROR: BTS is not discovered yet. Use 'discover' command or wait for auto discovery
    _re_failure = re.compile(r"ERROR:|ERR:")

    def _parse_failure(self, line):
        if self._regex_helper.search_compiled(BtsInfo._re_failure, line):
            self.set_exception(CommandFailure(self, f"Error: {line}"))

    def _fill_dict(self, matched):
        matched_length = len(matched)
        if matched_length == 4:
            self.current_ret[self._current_main_header] = {self._clean_key(key): convert_to_number(value)
                                                           for key, value in zip(self._columns_headers, matched)}
        elif matched_length == 2 or matched_length == 3:
            if matched_length == 2:
                matched.append("")
            states_object = matched[0]
            self.current_ret[self._current_main_header][states_object] = {self._clean_key(key): convert_to_number(value)
                                                                          for key, value in zip(self._columns_headers,
                                                                                                matched)}

    @staticmethod
    def _clean_key(key):
        signs = [
            (" ", "_"),
            ("-", ""),
            ("(", ""),
            (")", ""),
            ("\r", "")
        ]
        key = key.lower()
        for sign in signs:
            key = key.replace(sign[0], sign[1])
        return key


